func ptrEvaluation(p unsafe.Pointer, c int32) any {
	r := (*agentevaluation.Evaluation)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 2:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 3:
		return (*string)(unsafe.Pointer(&r.AgentDefinitionID))
	case 4:
		return (*string)(unsafe.Pointer(&r.SourceRunID))
	case 5:
		return (**string)(unsafe.Pointer(&r.EvalCaseID))
	case 6:
		return (*string)(unsafe.Pointer(&r.Status))
	case 7:
		return (*string)(unsafe.Pointer(&r.Trigger))
	case 8:
		return (*string)(unsafe.Pointer(&r.SubjectType))
	case 9:
		return (*string)(unsafe.Pointer(&r.SubjectID))
	case 10:
		return &r.Input
	case 11:
		return &r.DefinitionVersion
	case 12:
		return &r.PromptVersion
	case 13:
		return &r.Model
	case 14:
		return (*string)(unsafe.Pointer(&r.ProviderID))
	case 15:
		return &r.Reply
	case 16:
		return &r.Actions
	case 17:
		return &r.Comparison
	case 18:
		return (*int64)(unsafe.Pointer(&r.OriginalProposals))
	case 19:
		return (*int64)(unsafe.Pointer(&r.ToolCallsUsed))
	case 20:
		return &r.Checks
	case 21:
		return &r.Judge
	case 22:
		return &r.CaseScore
	case 23:
		return &r.Fingerprint
	case 24:
		return (**string)(unsafe.Pointer(&r.SuiteRunID))
	case 25:
		return (**int64)(unsafe.Pointer(&r.SuiteOrdinal))
	case 26:
		return (**string)(unsafe.Pointer(&r.TrialProviderID))
	case 27:
		return &r.WorkflowID
	case 28:
		return &r.ErrorMessage
	case 29:
		return (**string)(unsafe.Pointer(&r.RequestedByUserID))
	case 30:
		return &r.StartedAt
	case 31:
		return &r.CompletedAt
	case 32:
		return &r.Version
	case 33:
		return &r.CreatedAt
	case 34:
		return &r.UpdatedAt
	}
	return nil
}

func valueEvaluation(p unsafe.Pointer, c int32) any {
	r := (*agentevaluation.Evaluation)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.BusinessUnitID)
	case 2:
		return string(r.OrganizationID)
	case 3:
		return string(r.AgentDefinitionID)
	case 4:
		if r.SourceRunID == "" {
			return nil
		}
		return string(r.SourceRunID)
	case 5:
		if r.EvalCaseID == nil {
			return nil
		}
		return string(*r.EvalCaseID)
	case 6:
		return string(r.Status)
	case 7:
		return string(r.Trigger)
	case 8:
		if r.SubjectType == "" {
			return nil
		}
		return string(r.SubjectType)
	case 9:
		if r.SubjectID == "" {
			return nil
		}
		return string(r.SubjectID)
	case 10:
		if r.Input == "" {
			return nil
		}
		return r.Input
	case 11:
		return r.DefinitionVersion
	case 12:
		if r.PromptVersion == "" {
			return nil
		}
		return r.PromptVersion
	case 13:
		if r.Model == "" {
			return nil
		}
		return r.Model
	case 14:
		if r.ProviderID == "" {
			return nil
		}
		return string(r.ProviderID)
	case 15:
		if r.Reply == "" {
			return nil
		}
		return r.Reply
	case 16:
		if r.Actions == nil {
			return keel.EmptyJSONArray
		}
		return r.Actions
	case 17:
		if r.Comparison == nil {
			return nil
		}
		return *r.Comparison
	case 18:
		return int64(r.OriginalProposals)
	case 19:
		return int64(r.ToolCallsUsed)
	case 20:
		if r.Checks == nil {
			return nil
		}
		return *r.Checks
	case 21:
		if r.Judge == nil {
			return nil
		}
		return *r.Judge
	case 22:
		if r.CaseScore == nil {
			return nil
		}
		return *r.CaseScore
	case 23:
		if r.Fingerprint == nil {
			return nil
		}
		return *r.Fingerprint
	case 24:
		if r.SuiteRunID == nil {
			return nil
		}
		return string(*r.SuiteRunID)
	case 25:
		if r.SuiteOrdinal == nil {
			return nil
		}
		return int64(*r.SuiteOrdinal)
	case 26:
		if r.TrialProviderID == nil {
			return nil
		}
		return string(*r.TrialProviderID)
	case 27:
		if r.WorkflowID == "" {
			return nil
		}
		return r.WorkflowID
	case 28:
		if r.ErrorMessage == "" {
			return nil
		}
		return r.ErrorMessage
	case 29:
		if r.RequestedByUserID == nil {
			return nil
		}
		return string(*r.RequestedByUserID)
	case 30:
		if r.StartedAt == nil {
			return nil
		}
		return *r.StartedAt
	case 31:
		if r.CompletedAt == nil {
			return nil
		}
		return *r.CompletedAt
	case 32:
		return r.Version
	case 33:
		return r.CreatedAt
	case 34:
		return r.UpdatedAt
	}
	return nil
}

